/* Kartenbasis: ausschliesslich aus den hinterlegten Kursmaterialien. */
const BASE_CARDS = [
 {id:'p01',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wie definiert Heywood & Laing Politik?',a:'Politik ist die Tätigkeit, durch die Menschen die allgemeinen Regeln, nach denen sie leben, <b>festlegen, bewahren und ändern</b>.',s:'Vorlesung 1, Folie 15'},
 {id:'p02',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wie definiert Patzelt Politik?',a:'Politik ist menschliches Handeln, das auf die Herstellung und Durchsetzung <b>allgemein verbindlicher Regelungen und Entscheidungen</b> in und zwischen Gruppen abzielt.',s:'Vorlesung 1, Folie 16; Patzelt (2023), Kap. 1, S. 11'},
 {id:'p03',topic:'Politik & Politikwissenschaft',type:'Vergleich',q:'Wofür stehen Polity, Politics und Policy?',a:'<b>Polity</b>: struktureller Rahmen / politisches System. <b>Politics</b>: Prozess aus Streit, Verhandlung und Entscheidung. <b>Policy</b>: materieller Inhalt von Politikprogrammen in konkreten Feldern.',s:'Vorlesung 1, Folie 14'},
 {id:'p04',topic:'Politik & Politikwissenschaft',type:'Verständnis',q:'Welche drei Bedingungen begründen nach Heywood & Laing den Bedarf für Politik?',a:'<b>Vielfalt bzw. Uneinigkeit</b>, <b>Wahlmöglichkeit bzw. Freiheit</b> und <b>Knappheit</b>.',s:'Vorlesung 1, Folie 13'},
 {id:'p05',topic:'Politik & Politikwissenschaft',type:'Lückentext',q:'Ergänze: Klimapolitik umfasst Regeln, die den menschengemachten Klimawandel ________ und/oder seine negativen Folgen ________.',a:'… den menschengemachten Klimawandel <b>begrenzen</b> und/oder seine negativen Folgen <b>bewältigen</b>.',s:'Vorlesung 1, Folie 21'},
 {id:'p06',topic:'Politik & Politikwissenschaft',type:'Vergleich',q:'Was unterscheidet Klimaschutz und Klimaanpassung?',a:'<b>Klimaschutz</b> zielt darauf, den menschengemachten Klimawandel zu begrenzen. <b>Klimaanpassung</b> zielt darauf, negative Folgen des Klimawandels zu bewältigen.',s:'Vorlesung 1, Folie 21'},
 {id:'p07',topic:'Politik & Politikwissenschaft',type:'Verständnis',q:'Welche vier Grundfragen strukturierten die Klimapolitik in der Vorlesung?',a:'(1) Geeignete Regeln für systemische Risiken? (2) Wer trägt Kosten? (3) Welche Technologien, Branchen und Regionen profitieren? (4) Wer entscheidet, wie entschieden wird?',s:'Vorlesung 1, Folien 23–26'},
 {id:'p08',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wie definiert Patzelt Wissenschaft?',a:'Wissenschaft zielt auf Aussagen, die Aussagen des „gesunden Menschenverstandes“ an <b>empirischem und logischem Wahrheitsgehalt</b> überlegen sind.',s:'Vorlesung 1, Folie 28; Patzelt (2023), Kap. 1, S. 18'},
 {id:'p09',topic:'Politik & Politikwissenschaft',type:'Verständnis',q:'Welche zwei Prüfungen braucht eine wissenschaftliche Aussage laut Kurslogik?',a:'Sie muss <b>empirisch</b> tragfähig sein und ihre Schlussfolgerung muss <b>logisch</b> gerechtfertigt sein. Richtige Ausgangsinformationen allein reichen nicht.',s:'Patzelt (2023), Kap. 1, S. 18; Transkription: SVP Graubünden'},
 {id:'p10',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Was ist der ökologische Fehlschluss?',a:'Von einem Merkmal einer <b>Gruppe</b> wird unzulässig auf das Merkmal eines <b>Individuums</b> geschlossen.',s:'Transkription: SVP Graubünden Stereotype und Generalisierungen'},
 {id:'p11',topic:'Politik & Politikwissenschaft',type:'Verständnis',q:'Warum ist Politikwissenschaft laut Vorlesung keine einzelne Methode?',a:'Sie ist <b>mehrperspektivisch</b> und nutzt verschiedene Zugänge, um zu verstehen und zu erklären, wie Regeln und Entscheidungen hervorgebracht, bewahrt, umgesetzt, infrage gestellt und verändert werden.',s:'Vorlesung 1, Folie 33'},
 {id:'p12',topic:'Politik & Politikwissenschaft',type:'Vergleich',q:'Wofür stehen Hobbes’ Geometrie- und Tocquevilles Drachen-Metapher?',a:'<b>Hobbes</b>: Politik folgt konstruierbaren Regeln. <b>Tocqueville</b>: Politische Entwicklung entsteht aus „Schnur“ (Strukturen) und „Wind“ (situative Faktoren).',s:'Vorlesung 1, Folien 29–30'},
 {id:'p13',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Was meint „konkurrierendes Selbstwissen“?',a:'Der Forschungsgegenstand enthält bereits Alltagswissen und Deutungsmuster der politisch Handelnden. Politikwissenschaftliche Befunde konkurrieren daher mit diesem vorhandenen Wissen.',s:'Vorlesung 1, Folie 31; Patzelt (2023), Kap. 1, S. 30–31'},
 {id:'p14',topic:'Politik & Politikwissenschaft',type:'Verständnis',q:'Nenne die vier Forschungserschwernisse der Politikwissenschaft nach der Vorlesung.',a:'<b>Komplexität</b> politischer Wirklichkeit; <b>Geschichtlichkeit</b>; <b>konkurrierendes Selbstwissen</b> des Forschungsgegenstands; <b>Verbundenheit</b> der Forschenden mit dem Gegenstand.',s:'Vorlesung 1, Folie 31'},
 {id:'p15',topic:'Politik & Politikwissenschaft',type:'Anwendung',q:'Warum sind Aussagen über „Geschichtsgesetze“ nach Patzelt problematisch?',a:'Menschen können auf Vorhersagen reagieren und damit Voraussetzungen ihrer Richtigkeit verändern. Aus vergangenen Trends lassen sich daher keine zwingenden Gesetze des künftigen Verlaufs ableiten.',s:'Patzelt (2023), Kap. 1, S. 28–29'},
 {id:'p16',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wofür steht das MINK-Schema?',a:'Für vier zentrale Dimensionen der Politik: <b>Macht, Ideologie, Normen und Kommunikation</b>.',s:'Patzelt (2023), Kap. 1, S. 11–12'},
 {id:'p17',topic:'Politik & Politikwissenschaft',type:'Verständnis',q:'Was bedeutet „Verbundenheit der Politikwissenschaftler mit ihrem Gegenstand“?',a:'Forschende teilen teils das Alltagswissen ihres Gegenstands und ihre Forschung kann den Gegenstand verändern, etwa durch Befragungen oder die öffentliche Wirkung von Ergebnissen.',s:'Patzelt (2023), Kap. 1, S. 31–33'},
 {id:'p18',topic:'Politik & Politikwissenschaft',type:'Anwendung',q:'Ordne die Frage „Wer gehört zur politischen Gemeinschaft?“ einer Dimension zu.',a:'<b>Polity</b>, denn es geht um den strukturellen Rahmen und die Grenzen der politischen Gemeinschaft.',s:'Vorlesung 1, Folie 14; Vorlesung 3, Folie 30'},

 {id:'m01',topic:'Macht',type:'Definition',q:'Wie definiert Max Weber Macht?',a:'Macht ist jede Chance, innerhalb einer sozialen Beziehung den eigenen Willen <b>auch gegen Widerstreben</b> durchzusetzen – unabhängig davon, worauf diese Chance beruht.',s:'Vorlesung 2, Folie 8'},
 {id:'m02',topic:'Macht',type:'Verständnis',q:'Welche drei historischen Prämissen des Machtverständnisses nennt Popitz?',a:'Machtordnungen sind <b>menschen­gemacht</b>; Macht ist in sozialen Beziehungen <b>allgegenwärtig</b>; Macht <b>begrenzt Freiheit</b> und bedarf darum der Rechtfertigung.',s:'Vorlesung 2, Folie 10; Popitz (1992), S. 12–20'},
 {id:'m03',topic:'Macht',type:'Definition',q:'Was ist Aktionsmacht bei Popitz?',a:'Die Fähigkeit, andere Menschen zu <b>verletzen oder zu töten</b> (Verletzungskraft). Ihre vitale Bedingtheit ist die Verwundbarkeit des menschlichen Körpers.',s:'Vorlesung 2, Folie 11'},
 {id:'m04',topic:'Macht',type:'Definition',q:'Was ist instrumentelle Macht bei Popitz?',a:'Die Fähigkeit, <b>Angst und Hoffnung</b> zu erzeugen. Sie beruht auf der Zukunftsorientiertheit des Menschen.',s:'Vorlesung 2, Folie 11'},
 {id:'m05',topic:'Macht',type:'Definition',q:'Was ist autoritative Macht bei Popitz?',a:'Die Fähigkeit, <b>Massstäbe zu setzen</b>. Sie knüpft an Massstabs-, Orientierungs- und Anerkennungsbedürftigkeit an.',s:'Vorlesung 2, Folie 11'},
 {id:'m06',topic:'Macht',type:'Definition',q:'Was ist datensetzende Macht bei Popitz?',a:'Macht durch <b>technische Handlungsfähigkeit</b>; sie beruht auf der Gebundenheit an eine artifiziell veränderte Objektwelt.',s:'Vorlesung 2, Folie 11'},
 {id:'m07',topic:'Macht',type:'Anwendung',q:'Welche Popitz-Form illustriert die Räumung eines Protestcamps durch Polizeikräfte?',a:'<b>Aktionsmacht</b>, weil die physische Verletzungs- bzw. Gewaltfähigkeit eingesetzt wird.',s:'Vorlesung 2, Folien 15 und 37 (Lösungsvorschlag)'},
 {id:'m08',topic:'Macht',type:'Anwendung',q:'Welche Popitz-Form illustriert ein Förderprogramm mit Bussandrohung für alte Ölheizungen?',a:'<b>Instrumentelle Macht</b>: Zuschuss und Busse erzeugen Hoffnung bzw. Angst und beeinflussen zukunftsbezogenes Handeln.',s:'Vorlesung 2, Folien 15 und 37 (Lösungsvorschlag)'},
 {id:'m09',topic:'Macht',type:'Anwendung',q:'Welche Popitz-Form illustriert eine autofreie Innenstadt?',a:'<b>Datensetzende Macht</b>: Die Gestaltung der materiellen Umwelt verändert Handlungsmöglichkeiten.',s:'Vorlesung 2, Folien 15 und 37 (Lösungsvorschlag)'},
 {id:'m10',topic:'Macht',type:'Vergleich',q:'Was unterscheidet „Macht über“ von „Macht zu“?',a:'<b>Macht über</b> ist Kontrolle durch z. B. Gewalt, Sanktionen, Autorität oder Umweltgestaltung und freiheitsbeschränkend. <b>Macht zu</b> ist gemeinsames Handeln und die Möglichkeit, Neues hervorzubringen; sie ist freiheitsermöglichend.',s:'Vorlesung 2, Folien 20–23'},
 {id:'m11',topic:'Macht',type:'Verständnis',q:'Wie versteht Hannah Arendt Macht und wie grenzt sie Gewalt ab?',a:'Macht entsteht, wenn Menschen sich zusammentun und <b>gemeinsam handeln</b>; sie braucht Legitimität. Gewalt ist keine Machtform, sondern kann Macht zerstören.',s:'Vorlesung 2, Folien 21–23'},
 {id:'m12',topic:'Macht',type:'Verständnis',q:'Welche Ergänzung bringt Foucault in den Machtbegriff?',a:'Macht wirkt auch <b>produktiv bzw. konstitutiv</b>: Moderne Subjekte sind Produkt von Macht. Disziplinarmacht ist neben souveräner Macht zentral; Diskurse gehören zur Umweltgestaltung.',s:'Vorlesung 2, Folien 24–27'},
 {id:'m13',topic:'Macht',type:'Definition',q:'Was analysiert die erste Dimension der Macht nach Lukes?',a:'<b>Entscheidungsfindung</b> in formalen politischen Arenen. Macht ist sichtbar, transparent und vergleichsweise leicht messbar; methodisch werden Stimmen oder Ergebnisse ausgezählt.',s:'Vorlesung 2, Folie 29'},
 {id:'m14',topic:'Macht',type:'Definition',q:'Was ergänzt die zweite Dimension der Macht nach Lukes?',a:'Sie umfasst <b>Agenda-Setting</b>: Neben formalen Arenen analysiert sie informelle „Korridore der Macht“. Macht kann unsichtbar sein, aber durch Insiderwissen bzw. Ethnographie sichtbar werden.',s:'Vorlesung 2, Folie 29'},
 {id:'m15',topic:'Macht',type:'Definition',q:'Was ergänzt die dritte Dimension der Macht nach Lukes?',a:'Sie umfasst <b>Präferenzgestaltung</b>. Macht prägt Wahrnehmungen und Präferenzen, ist weitgehend unsichtbar und wird über Ideologiekritik untersucht.',s:'Vorlesung 2, Folie 29'},
 {id:'m16',topic:'Macht',type:'Vergleich',q:'Welcher Analysezugang gehört zu welcher Lukes-Dimension?',a:'1: Stimmen/Entscheidungsergebnisse auszählen. 2: Ethnographie informeller Machtkorridore. 3: Ideologiekritik der falsch verstandenen eigenen materiellen Interessen.',s:'Vorlesung 2, Folie 29'},
 {id:'m17',topic:'Macht',type:'Anwendung',q:'Ordne die langjährige Nichtbehandlung fossiler Brennstoffe bei Klimakonferenzen nach Lukes ein.',a:'<b>Zweite Dimension</b>: Das Thema wird über Agenda-Setting bzw. Nicht-Entscheidung aus der formalen Behandlung herausgehalten.',s:'Vorlesung 3, Folie 6'},
 {id:'m18',topic:'Macht',type:'Anwendung',q:'Warum ist der CO₂-Fussabdruck als ausschliesslich individuelles Konsumproblem ein Beispiel für die dritte Lukes-Dimension?',a:'Er kann Präferenzen und Wahrnehmungen so prägen, dass Klimaschutz als private statt als strukturelle Frage erscheint. Das entspricht diskursiver Präferenzgestaltung.',s:'Vorlesung 3, Folie 6'},

 {id:'i01',topic:'Ideologien',type:'Vergleich',q:'Welche drei Bedeutungen von „Ideologie“ unterscheidet die Vorlesung?',a:'(1) rigide Denkmuster im Individuum (abwertend), (2) Herrschaftsinstrument in der Gesellschaft (kritisch), (3) handlungsleitendes Paradigma im politischen Wettbewerb (neutral-analytisch).',s:'Vorlesung 3, Folie 3'},
 {id:'i02',topic:'Ideologien',type:'Definition',q:'Wie definiert Heywood eine Ideologie?',a:'Ein mehr oder weniger kohärentes <b>Bündel von Ideen</b>, das die Grundlage für organisiertes politisches Handeln zur Erhaltung, Veränderung oder zum Sturz eines Machtsystems bildet.',s:'Vorlesung 3, Folie 13; Heywood (2021), Kap. 1'},
 {id:'i03',topic:'Ideologien',type:'Verständnis',q:'Welche drei Elemente enthalten laut Vorlesung alle politischen Ideologien?',a:'Eine Darstellung der bestehenden Ordnung, ein Modell der gewünschten Zukunft („gute Gesellschaft“) und eine Erklärung, wie politischer Wandel von der ersten zur zweiten geführt werden soll.',s:'Vorlesung 3, Folie 14'},
 {id:'i04',topic:'Ideologien',type:'Verständnis',q:'Nenne drei Funktionen von Ideologien.',a:'Sie machen die Welt begreiflich, verleihen Politik moralische Ziele bzw. Zwecke und bilden bzw. erhalten Gemeinschaften.',s:'Vorlesung 3, Folie 15'},
 {id:'i05',topic:'Ideologien',type:'Definition',q:'Was unterscheidet dichte von thin-centered Ideologien?',a:'<b>Dichte/starke</b> Ideologien haben Kern-, benachbarte und periphere Begriffe. <b>Thin-centered</b> Ideologien verfügen über ein dünnes Zentrum und benötigen oft Ergänzung durch andere Ideologien.',s:'Vorlesung 3, Folie 16; Heywood (2021), Kap. 1'},
 {id:'i06',topic:'Ideologien',type:'Definition',q:'Wie versteht Marx Ideologie?',a:'Als kritisches Konzept von <b>Täuschung und Mystifizierung</b>: Ideologie spiegelt Interessen und Perspektive der herrschenden Klasse und verschleiert Klassenwidersprüche.',s:'Heywood (2021), Kap. 1, S. 3–4; Vorlesung 3, Folie 7'},
 {id:'i07',topic:'Ideologien',type:'Definition',q:'Was bedeutet Hegemonie bei Gramsci?',a:'Die Dominanz bürgerlicher Ideen und Überzeugungen, die konkurrierende Ansichten verdrängt und zum allgemeinen Weltbild wird.',s:'Heywood (2021), Kap. 1, S. 5'},
 {id:'i08',topic:'Ideologien',type:'Verständnis',q:'Wie hängen bei Marx materieller Basis und ideellem Überbau zusammen?',a:'Der ideelle Überbau wird von der materiellen Basis geprägt und legitimiert bzw. stützt diese zugleich; die Beziehung ist wechselseitig dargestellt.',s:'Vorlesung 3, Folie 8'},
 {id:'i09',topic:'Ideologien',type:'Definition',q:'Welche Kernbegriffe prägen den Liberalismus?',a:'<b>Freiheit, Individuum und Vernunft</b>. Zentrale Nachbarbegriffe sind u. a. Rechte, Eigentum, Markt und Toleranz.',s:'Vorlesung 3, Folie 20'},
 {id:'i10',topic:'Ideologien',type:'Verständnis',q:'Wie beschreibt der Liberalismus Gesellschaft und gute Gesellschaft?',a:'Gesellschaft besteht aus Individuen mit Vernunft und Rechten; Gefahr ist konzentrierte willkürliche Macht. Gute Gesellschaft schützt unterschiedliche Lebensentwürfe durch Verfassungsstaat und Toleranz.',s:'Vorlesung 3, Folie 20'},
 {id:'i11',topic:'Ideologien',type:'Vergleich',q:'Wie unterscheidet sich klassischer von sozialem Liberalismus beim Freiheitsbegriff?',a:'Klassischer Liberalismus betont <b>negative Freiheit</b> (von Eingriffen), Minimalstaat und Markt. Sozialer Liberalismus betont <b>positive Freiheit</b> bzw. Selbstentfaltung, Chancengleichheit und den Staat als Ermöglicher.',s:'Vorlesung 3, Folie 21'},
 {id:'i12',topic:'Ideologien',type:'Definition',q:'Welche Kernbegriffe prägen den Konservatismus?',a:'<b>Tradition, Unvollkommenheit und organische Gesellschaft</b>. Wichtige Nachbarbegriffe sind Autorität, Hierarchie, Eigentum und Gemeinschaft.',s:'Vorlesung 3, Folie 22'},
 {id:'i13',topic:'Ideologien',type:'Verständnis',q:'Wie erklärt der Konservatismus gesellschaftlichen Wandel?',a:'Vorsichtig und schrittweise: <b>„Verändern, um zu bewahren“</b>. Radikale Blaupausen werden abgelehnt, weil Vernunft begrenzt und Institutionen überlieferte Erfahrung speichern.',s:'Vorlesung 3, Folie 22'},
 {id:'i14',topic:'Ideologien',type:'Definition',q:'Welche Kernbegriffe prägen den Sozialismus?',a:'<b>Gemeinschaft, Gleichheit und Solidarität</b>. Wichtige Nachbarbegriffe sind soziale Klasse, Gemeineigentum und Sozialpolitik.',s:'Vorlesung 3, Folie 23'},
 {id:'i15',topic:'Ideologien',type:'Verständnis',q:'Wie beschreibt der Sozialismus Gesellschaft, gute Gesellschaft und Wandel?',a:'Kapitalismus erzeugt Klassen und Ungleichheit. Ziel ist eine Gemeinschaft von Gleichen; Wandel erfolgt durch kollektives Handeln – Revolution oder schrittweise Reform.',s:'Vorlesung 3, Folie 23'},
 {id:'i16',topic:'Ideologien',type:'Anwendung',q:'Wie deutet die Vorlesung Klimakrise aus liberaler Perspektive?',a:'Als <b>Marktversagen</b> und Schaden für die Freiheit anderer. Beispiel: CO₂-Abgabe als Preissignal, dessen Einnahmen zurückverteilt werden.',s:'Vorlesung 3, Folie 27'},
 {id:'i17',topic:'Ideologien',type:'Anwendung',q:'Welche Spannung identifiziert die Vorlesung zwischen Liberalismus und Klimakrise?',a:'Das Schadensprinzip stösst an Grenzen, weil Schaden diffus, global und zukünftig ist; zudem entsteht Spannung zwischen staatlicher Neutralität und veränderten Lebensstilen.',s:'Vorlesung 3, Folie 27'},
 {id:'i18',topic:'Ideologien',type:'Anwendung',q:'Welche Spannung bringt die Klimakrise für den Konservatismus hervor?',a:'<b>Bewahren</b> kann raschen, tiefgreifenden Wandel erfordern. Zudem stehen Erfahrung und wissenschaftliche Prognose sowie lokale Verwurzelung und globales Problem in Spannung.',s:'Vorlesung 3, Folie 28'},
 {id:'i19',topic:'Ideologien',type:'Anwendung',q:'Wie deutet die Vorlesung Klimakrise aus sozialistischer Perspektive?',a:'Als vom Kapitalismus erzeugtes <b>Gerechtigkeitsproblem</b>. Zentral ist die Forderung nach einem gerechten Übergang („just transition“).',s:'Vorlesung 3, Folie 29'},
 {id:'i20',topic:'Ideologien',type:'Verständnis',q:'Welche Spannung identifiziert die Vorlesung zwischen Sozialismus und Klimakrise?',a:'Produktivistische Traditionen verbinden Fortschritt mit Industrie und Wachstum; dies kollidiert mit Ökologie bzw. Dringlichkeit. Genannt werden Ökosozialismus, Suffizienz und Degrowth als Neukonfigurationen.',s:'Vorlesung 3, Folie 29'},
 {id:'i21',topic:'Ideologien',type:'Vergleich',q:'Welche gemeinsame Herausforderung vieler westlicher Ideologien nennt die Vorlesung?',a:'<b>Anthropozentrismus</b>: Freiheit, Tradition und Gleichheit beziehen sich primär auf Menschen; Ökologismus rückt dagegen Natur in den Kern.',s:'Vorlesung 3, Folien 30 und 32'},
 {id:'i22',topic:'Ideologien',type:'Anwendung',q:'Warum ist eine Regelung zu „Rechten der Natur“ auch eine Polity-Frage?',a:'Sie verschiebt die Grenze der politischen Gemeinschaft: Es wird relevant, <b>wer</b> als zu dieser Gemeinschaft gehörig gilt.',s:'Vorlesung 3, Folie 30'},

 {id:'p19',topic:'Politik & Politikwissenschaft',type:'Verständnis',q:'Wie soll das MINK-Schema in einer Analyse politischen Handelns verwendet werden?',a:'<b>Macht, Ideologie, Normen und Kommunikation</b> sind nach Patzelt keine voneinander losgelösten Faktoren, sondern wirken im politischen Handeln eng zusammen. Eine Analyse sollte deshalb für einen Fall fragen, welche Durchsetzungschancen, Deutungen, Regeln und Kommunikationszusammenhänge wirksam sind.',s:'Patzelt (2023), Kap. 1, S. 11–12'},
 {id:'p20',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wie definiert Patzelt Ideologie im MINK-Schema?',a:'Ideologie ist eine Vorstellung über Beschaffenheit oder Funktionsweise der zu gestaltenden Wirklichkeit, die mit dieser Wirklichkeit <b>nicht übereinstimmt</b>, dem Handeln aber dennoch als Wahrnehmungswirklichkeit zugrunde gelegt wird. Sie ist politisch folgenreich, weil Handlungsfolgen real sein können, auch wenn die zugrunde gelegte Situationsdefinition irreal ist.',s:'Patzelt (2023), Kap. 1, S. 11–12'},
 {id:'p21',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Was sind Normen nach Patzelt?',a:'Normen sind erstens formale oder informale Regeln, die dem eigenen Handeln zugrunde liegen. Zweitens sind sie gesellschaftliche Wissensbestände und Denkmuster, mit deren Hilfe Handeln anderer gedeutet und durch eigenes Handeln beantwortet wird.',s:'Patzelt (2023), Kap. 1, S. 12'},
 {id:'p22',topic:'Politik & Politikwissenschaft',type:'Zusammenhang',q:'Wie tragen Normen zu Rollen, Organisationen und Institutionen bei?',a:'Indem Regeln dem Handeln zugrunde gelegt werden, tragen sie zur Entstehung und Aufrechterhaltung von <b>Rollen und Rollenstrukturen</b> bei. Patzelt nennt Organisationen und Institutionen als Beispiele solcher Strukturen; Normen prägen damit nicht nur Einzelhandlungen, sondern auch ihre dauerhafte Ordnung.',s:'Patzelt (2023), Kap. 1, S. 12'},
 {id:'p23',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wie versteht Patzelt Kommunikation im MINK-Schema?',a:'Kommunikation ist der „Kitt“, der eine Gesellschaft zusammenhält. Gemeint ist nicht nur persönliche Kommunikation, sondern auch Kommunikation über Presse, Hörfunk, Fernsehen, Webseiten und soziale Medien.',s:'Patzelt (2023), Kap. 1, S. 12'},
 {id:'p24',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wofür stehen die vier Buchstaben des AGIL-Schemas?',a:'<b>A</b> steht für Anpassung an wechselnde Umweltanforderungen, <b>G</b> für Zielerreichung, <b>I</b> für Integration beziehungsweise Zusammenhalt und Kohärenz des Handelns, <b>L</b> für die Aufrechterhaltung kultureller Muster und Wertleitungen. Patzelt wendet diese dauerhaften Aufgaben auf politische Systeme wie Parteien, Parlamente und Staaten an.',s:'Patzelt (2023), Kap. 1, S. 12'},
 {id:'p25',topic:'Politik & Politikwissenschaft',type:'Zusammenhang',q:'Welche drei Teilprozesse des politischen Prozesses hebt Patzelt hervor?',a:'Erstens <b>Willensbildung</b>: Es wird geklärt, was verbindlich werden soll. Zweitens <b>Entscheidung</b>: Beschlüsse werden gefasst und Regeln gesetzt. Drittens <b>Implementation</b>: Entscheidungen werden in konkret wirkende Maßnahmen umgesetzt; Konflikte können in allen drei Phasen auftreten.',s:'Patzelt (2023), Kap. 1, S. 13'},
 {id:'p26',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Warum nennt Patzelt politische Strukturen das „Flussbett“ politischer Prozesse?',a:'Organisationen und Institutionen bilden die politischen Strukturen beziehungsweise die <b>Polity</b>, innerhalb oder durch die politisches Handeln abläuft. Sie formen den Rahmen der Prozesse, sind aber keine Naturtatsachen: Sie sind zeitweise stabile Produkte vergangener Prozesse und können verändert oder zerstört werden.',s:'Patzelt (2023), Kap. 1, S. 13'},
 {id:'p27',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Was ist eine Zufallsstichprobe?',a:'Eine Zufallsstichprobe liegt vor, wenn jedes Element der interessierenden Grundgesamtheit die <b>gleiche Chance</b> hat, in die Stichprobe zu gelangen, und nur der Zufall über die tatsächliche Auswahl entscheidet. Nach Patzelt ermöglicht erst dieser sorgfältig gesicherte Zufall Repräsentativität und mathematisch begründete Schlüsse von der Stichprobe auf die Grundgesamtheit.',s:'Patzelt (2023), Kap. 1, S. 16'},
 {id:'p28',topic:'Politik & Politikwissenschaft',type:'Vergleich',q:'Was unterscheidet Parameterschätzung und Signifikanztest?',a:'Eine <b>Parameterschätzung</b> schätzt Merkmale der Grundgesamtheit auf Grundlage von Stichprobendaten. Ein <b>Signifikanztest</b> fragt dagegen, mit welcher Wahrscheinlichkeit ein Stichprobenbefund auftreten würde, wenn er in der Grundgesamtheit gerade nicht vorläge.',s:'Patzelt (2023), Kap. 1, S. 16'},
 {id:'p29',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Was bedeutet Operationalisierung?',a:'Operationalisierung ist der Arbeitsprozess, durch den ein abstrakter theoretischer Begriff in konkrete Begriffe übersetzt wird, mit denen sich real Beobachtbares erfassen lässt. Beispielhaft geprüft wird also nicht nur, ob ein Begriff plausibel klingt, sondern wie er beobachtbar gemacht wird.',s:'Patzelt (2023), Kap. 1, S. 17, Fn. 13'},
 {id:'p30',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Wann ist eine Operationalisierung valide?',a:'Eine Operationalisierung ist <b>valide</b>, wenn die konkreten Begriffe oder Indikatoren tatsächlich genau das erfassen, was der abstrakte theoretische Begriff meint. Die Karte trennt damit die bloße Messbarkeit eines Merkmals von der Frage, ob wirklich das Gemeinte gemessen wird.',s:'Patzelt (2023), Kap. 1, S. 17, Fn. 13'},
 {id:'p31',topic:'Politik & Politikwissenschaft',type:'Definition',q:'Was ist der empirische Referent einer Aussage?',a:'Der empirische Referent ist der Gegenstand, auf den sich eine Aussage bezieht. Eine Aussage ist nach der im Text erläuterten Korrespondenztheorie dann empirisch wahr, wenn sie die Beschaffenheit dieses Sachverhalts so behauptet, wie sie tatsächlich vorliegt.',s:'Patzelt (2023), Kap. 1, S. 18, Fn. 14'},
 {id:'p32',topic:'Politik & Politikwissenschaft',type:'Vergleich',q:'Was bedeuten Verifikation, Falsifikation und Bekräftigung?',a:'<b>Verifikation</b> ist der erfolgreiche Nachweis, dass eine Aussage empirisch wahr ist; <b>Falsifikation</b> der Nachweis, dass sie empirisch falsch ist. Lässt sich eine Aussage trotz Falsifikationsversuchen nicht als falsch nachweisen, wird sie als <b>bekräftigt</b> behandelt – nicht als endgültig bewiesen.',s:'Patzelt (2023), Kap. 1, S. 18, Fn. 14'},
 {id:'p33',topic:'Politik & Politikwissenschaft',type:'Fehlerquelle',q:'Welche vier Regeln nennt Patzelt gegen Immunisierungsstrategien in der Politikwissenschaft?',a:'Betrachtungsperspektiven sollen kontrolliert und korrigiert werden; ebenso die Selektivität der Informationsgrundlagen. Aussagen sollen klar und auf empirischen sowie logischen Wahrheitsgehalt überprüfbar formuliert sein; falsche Aussagen sollen sichtbar korrigiert werden.',s:'Patzelt (2023), Kap. 1, S. 19'},
 {id:'p34',topic:'Politik & Politikwissenschaft',type:'Vergleich',q:'Was unterscheidet idiographisches und nomothetisches Vorgehen?',a:'<b>Idiographisch</b> heißt, politische Wirklichkeit in ihrer jeweiligen individuellen Eigenart zu beschreiben und zu verstehen. <b>Nomothetisch</b> heißt, allgemeine Aussagen über ihre Beschaffenheit anzustreben; Patzelt behandelt die Frage nach ihrer Reichweite als fallweise zu klärende Forschungsfrage.',s:'Patzelt (2023), Kap. 1, S. 27–28'},

 {id:'m19',topic:'Macht',type:'Verständnis',q:'Was meint Popitz mit der Machbarkeit von Machtordnungen?',a:'Machtordnungen sind nach Popitz nicht gottgegeben, naturgegeben oder durch unantastbare Traditionen geheiligt, sondern <b>menschengemacht</b>. Daraus folgt die Vorstellung, dass sie anders gestaltet und verändert werden können; gerade deshalb werden sie zum Gegenstand politischer Gestaltung und Kritik.',s:'Popitz (1992), S. 12–13; Vorlesung 2, Folie 10'},
 {id:'m20',topic:'Macht',type:'Definition',q:'Was bedeutet die Omnipräsenz von Macht bei Popitz?',a:'Macht wird als Element jeder Vergesellschaftung vermutet und ist damit in sozialen Beziehungen allgegenwärtig. Der Fokus liegt deshalb nicht nur auf Staat oder Regierung, sondern auf Machtbeziehungen unterschiedlichster Art; ein machtfreier Raum wird bei Popitz gerade zur schwierigen Frage.',s:'Popitz (1992), S. 16–17; Vorlesung 2, Folie 10'},
 {id:'m21',topic:'Macht',type:'Verständnis',q:'Warum bedarf Macht nach Popitz der Rechtfertigung?',a:'Macht begrenzt Freiheit. Weil Menschen die Möglichkeit haben sollen, ihre Selbstbestimmung gegen Einschränkungen zu verteidigen, stellt sich für Machtverhältnisse die Frage, <b>warum</b> sie bestehen und wie sie gerechtfertigt werden können.',s:'Popitz (1992), S. 18–20; Vorlesung 2, Folie 10'},
 {id:'m22',topic:'Macht',type:'Zusammenhang',q:'Welche drei Wirkungsweisen von Macht nennt Patzelt neben der Durchsetzungsmacht?',a:'Patzelt unterscheidet Macht nicht nur als Durchsetzung des eigenen Willens. Macht kann auch als <b>Verhinderungsmacht</b> wirken und bereits die Begriffe und Denkweisen prägen, mit denen überhaupt darüber beraten wird, was durchgesetzt oder verhindert werden soll.',s:'Patzelt (2023), Kap. 1, S. 11'},
 {id:'m23',topic:'Macht',type:'Verständnis',q:'Warum ist datensetzende Macht bei Popitz keine „Macht der Dinge“?',a:'Datensetzende Macht entsteht dadurch, dass Menschen technische und materielle Bedingungen herstellen, die später Handlungsmöglichkeiten strukturieren. Die Macht liegt somit nicht im Ding als selbständigem Akteur, sondern in einer vom Hersteller in die Objektwelt eingebauten, oft zunächst latenten Wirkungsmöglichkeit.',s:'Popitz (1992), S. 39–40; Vorlesung 2, Folie 11'},
 {id:'m24',topic:'Macht',type:'Vergleich',q:'Welche menschlichen Bedingungen liegen den vier Machtformen bei Popitz zugrunde?',a:'<b>Aktionsmacht</b> knüpft an körperliche Verwundbarkeit an, <b>instrumentelle Macht</b> an Zukunftsorientierung, <b>autoritative Macht</b> an das Bedürfnis nach Maßstäben, Orientierung und Anerkennung. <b>Datensetzende Macht</b> beruht auf der Bindung an eine künstlich veränderte Objektwelt und technische Handlungsfähigkeit.',s:'Vorlesung 2, Folie 11'},
 {id:'m25',topic:'Macht',type:'Anwendung',q:'Warum reicht es bei der Analyse einer politischen Entscheidung nicht, nur das Abstimmungsergebnis zu betrachten?',a:'Das Ergebnis erfasst vor allem die erste, sichtbare Lukes-Dimension der Macht. Zusätzlich kann Macht darüber wirken, welche Themen überhaupt auf die Agenda gelangen, und darüber, wie Wahrnehmungen und Präferenzen geformt werden; diese Ebenen bleiben in einer bloßen Stimmenzählung unsichtbar.',s:'Vorlesung 2, Folie 29'},
 {id:'m26',topic:'Macht',type:'Vergleich',q:'Wie unterscheiden sich Arendts und Webers Machtbegriffe im Kern?',a:'Weber definiert Macht als Chance, den eigenen Willen in einer sozialen Beziehung auch gegen Widerstreben durchzusetzen. Arendt versteht Macht dagegen als Fähigkeit, die entsteht, wenn Menschen sich zusammenschließen und gemeinsam handeln; sie betont damit eine freiheitsermöglichende, legitimitätsgebundene Dimension.',s:'Vorlesung 2, Folien 8 und 21–23'},

 {id:'i23',topic:'Ideologien',type:'Vergleich',q:'Was unterscheidet bei Heywood die Untersuchung von „Ideologie“ und von „Ideologien“?',a:'Die Untersuchung von <b>Ideologie</b> fragt nach einer Art politischen Denkens: etwa nach ihrer Rolle, Wahrheit, sozialen Wirkung und Abgrenzung zu anderen Denkformen. Die Untersuchung von <b>Ideologien</b> analysiert dagegen Inhalte bestimmter Traditionen wie Liberalismus, Sozialismus oder Feminismus.',s:'Heywood (2021), Kap. 1, S. 1–2'},
 {id:'i24',topic:'Ideologien',type:'Verständnis',q:'Warum ist der Ideologiebegriff laut Heywood besonders umstritten?',a:'Es gibt keine allgemein anerkannte Definition, sondern konkurrierende Begriffe. Zudem berührt Ideologie die umstrittene Beziehung zwischen Theorie und Praxis sowie zwischen Ideen, materiellem Leben und politischem Verhalten; historisch wurde der Begriff oft als politische Waffe gegen rivalisierende Ideen eingesetzt.',s:'Heywood (2021), Kap. 1, S. 2'},
 {id:'i25',topic:'Ideologien',type:'Definition',q:'Was meinte Antoine Destutt de Tracy ursprünglich mit „Ideologie“?',a:'De Tracy prägte den Begriff während der Französischen Revolution für eine <b>„Wissenschaft der Ideen“</b>. Er wollte die Ursprünge von Ideen objektiv untersuchen und verstand Ideologie zunächst nicht als Schimpfwort oder Herrschaftsinstrument.',s:'Heywood (2021), Kap. 1, S. 3'},
 {id:'i26',topic:'Ideologien',type:'Vergleich',q:'Wie unterscheidet sich ein neutrales von einem kritischen Ideologiebegriff?',a:'Ein <b>kritischer</b> Begriff bewertet Ideologie etwa als Täuschung, Herrschaftsinstrument oder falsches Bewusstsein. Ein <b>neutraler</b> sozialwissenschaftlicher Begriff versteht sie als handlungsorientiertes Ideenbündel; so verstanden kann Ideologie wahr oder falsch, offen oder geschlossen, befreiend oder unterdrückend sein.',s:'Heywood (2021), Kap. 1, S. 6–7'},
 {id:'i27',topic:'Ideologien',type:'Definition',q:'Was bedeutet „falsches Bewusstsein“ in der marxistischen Ideologiekritik?',a:'Ideologie kann nach marxistischer Perspektive Klassenwidersprüche verschleiern und dazu führen, dass untergeordnete oder ausgebeutete Gruppen ihre Lage und Interessen falsch verstehen. Dadurch fördert sie politische Passivität und stabilisiert die Ideen der herrschenden Klasse.',s:'Heywood (2021), Kap. 1, S. 4–5; Vorlesung 3, Folien 5–7'},
 {id:'i28',topic:'Ideologien',type:'Vergleich',q:'Wie unterscheidet Mannheim Ideologien und Utopien?',a:'Bei Mannheim sind <b>Ideologien</b> Ideen, die die bestehende Ordnung stützen und Interessen dominanter oder herrschender Gruppen ausdrücken. <b>Utopien</b> sind idealisierte Zukunftsbilder, die radikalen Wandel implizieren und den Interessen unterdrückter oder untergeordneter Gruppen dienen.',s:'Heywood (2021), Kap. 1, S. 5–6'},
 {id:'i29',topic:'Ideologien',type:'Vergleich',q:'Was unterscheidet bei Mannheim partikularen und totalen Ideologiebegriff?',a:'Der <b>partikulare</b> Ideologiebegriff bezieht sich auf Ideen und Überzeugungen bestimmter Individuen, Gruppen oder Parteien. Der <b>totale</b> Ideologiebegriff umfasst die gesamte Weltanschauung einer sozialen Klasse, einer Gesellschaft oder sogar einer historischen Epoche.',s:'Heywood (2021), Kap. 1, S. 5–6'},
 {id:'i30',topic:'Ideologien',type:'Definition',q:'Wie kritisiert eine konservative Perspektive Ideologie?',a:'Sie sieht Ideologien als abstrakte Denksysteme, die eine komplexe soziale Realität zu stark vereinfachen und verzerren können. Wegen ihrer Skepsis gegenüber Rationalismus und Fortschrittsentwürfen bevorzugt diese Perspektive Erfahrung und Geschichte als Leitlinien politischen Handelns und verbindet Ideologie mit Dogmatismus.',s:'Heywood (2021), Kap. 1, S. 6'},
 {id:'i31',topic:'Ideologien',type:'Definition',q:'Was bedeutet Pragmatismus im politischen Sinn?',a:'Pragmatismus orientiert sich eher an praktischen Umständen und Zielen als an Prinzipien oder ideologischen Zielsetzungen. Politische Maßnahmen und Aussagen werden danach beurteilt, was funktioniert; laut Heywood kann das ideologisches Wunschdenken begrenzen, wird von Kritikern aber als Prinzipienlosigkeit gedeutet.',s:'Heywood (2021), Kap. 1, S. 6–7'},
 {id:'i32',topic:'Ideologien',type:'Vergleich',q:'Worin unterscheiden sich politische Ideologie und politische Theorie nach Heywood?',a:'Politische Theorie untersucht vor allem zentrale Ideen und Konzepte sowie die Argumente bedeutender Denkerinnen und Denker; sie stellt häufig normative Fragen. Ideologien bieten dagegen eigenständige Deutungsrahmen, verbinden Beschreibung der Gegenwart mit einem Zielbild und sind auf politische Veränderung ausgerichtet.',s:'Heywood (2021), Kap. 1, S. 8–10'},
 {id:'i33',topic:'Ideologien',type:'Vergleich',q:'Was bedeuten deskriptiv und normativ im Zusammenhang mit Ideologien?',a:'<b>Deskriptiv</b> beschreibt, was ist, ohne Werturteil. <b>Normativ</b> gibt Werte und Verhaltensmaßstäbe vor, also was sein soll; Ideologien bewegen sich nach Heywood an der Schnittstelle beider Ebenen, weil sie bestehende Ordnung deuten und zugleich eine gewünschte Zukunft entwerfen.',s:'Heywood (2021), Kap. 1, S. 9–10'},
 {id:'i34',topic:'Ideologien',type:'Verständnis',q:'Warum sind Ideologien nach Heywood nur „mehr oder weniger“ kohärent?',a:'Ideologien sind keine hermetisch abgeschlossenen Systeme: Sie überschneiden sich, gehen ineinander über und enthalten teils rivalisierende Traditionen. Diese Offenheit kann Weiterentwicklung und hybride Formen ermöglichen; zugleich kann gerade innerhalb einer Ideologie heftig um ihre „wahre“ Gestalt gestritten werden.',s:'Heywood (2021), Kap. 1, S. 10'},
 {id:'i35',topic:'Ideologien',type:'Definition',q:'Was sind „essenziell umstrittene Konzepte“?',a:'Das sind Konzepte, über deren Bedeutung so tiefgreifende Kontroversen bestehen, dass keine feste, einvernehmliche Definition entsteht. Heywood zählt Ideologie selbst dazu und verweist darauf, dass auch Begriffe wie Freiheit, Demokratie, Gerechtigkeit oder Gleichheit von verschiedenen Seiten unterschiedlich gefüllt werden.',s:'Heywood (2021), Kap. 1, S. 10'},
 {id:'i36',topic:'Ideologien',type:'Verständnis',q:'Wie erklärt Heywood die Identität einer Ideologie über ihre Konzeptstruktur?',a:'Eine Ideologie lässt sich über eine Morphologie aus <b>zentralen, angrenzenden und peripheren Konzepten</b> erkennen. Nicht jeder einzelne Bestandteil muss immer vorhanden sein; werden jedoch besonders geschätzte Prinzipien aufgegeben oder gegensätzliche übernommen, kann die ideologische Identität verloren gehen oder in eine andere Tradition übergehen.',s:'Heywood (2021), Kap. 1, S. 10–11'},
 {id:'i37',topic:'Ideologien',type:'Vergleich',q:'Was unterscheidet klassische und neue Ideologien bei Heywood?',a:'Klassische Ideologien wie Liberalismus, Konservatismus und Sozialismus entstanden als gegensätzliche Versuche, die Industriegesellschaft zu gestalten, und hatten einen starken wirtschaftlichen Fokus. Neue Ideologien verleihen Themen wie Geschlechtergleichstellung, ökologischer Nachhaltigkeit oder kultureller Vielfalt besonderes Gewicht und stehen in komplexer Beziehung zu klassischen Traditionen.',s:'Heywood (2021), Kap. 1, S. 11–13'},
 {id:'i38',topic:'Ideologien',type:'Zusammenhang',q:'Welche drei Veränderungen verbindet Heywood mit neuen Ideologien?',a:'Erstens verlagert sich der Schwerpunkt von Wirtschaft zu Kultur. Zweitens verschiebt sich Aufmerksamkeit von Sozialpolitik zu Identitätspolitik; drittens werden klassische Ideologien im Zuge der Dekolonisierung des Lehrplans stärker kritisch geprüft. Diese drei Entwicklungen markieren Veränderungen des ideologischen Feldes, nicht das Verschwinden klassischer Ideologien.',s:'Heywood (2021), Kap. 1, S. 13–14'},
 {id:'i39',topic:'Ideologien',type:'Verständnis',q:'Welche unterschiedlichen Deutungen der Links-Rechts-Unterscheidung nennt Heywood?',a:'Links und rechts können gegensätzliche Haltungen zu Wandel markieren: links eher Fortschritt und Veränderung, rechts eher Verteidigung des Status quo. Sie können außerdem unterschiedliche Positionen zu Wirtschaftsordnung und Staat oder – bei Bobbio – unterschiedliche Einstellungen zur Gleichheit bezeichnen.',s:'Heywood (2021), Kap. 1, S. 15–16'},
 {id:'i40',topic:'Ideologien',type:'Fehlerquelle',q:'Warum ist ein lineares Links-Rechts-Spektrum nur begrenzt aussagekräftig?',a:'Eine einzige Achse kann widersprüchliche Elemente innerhalb einer Ideologie nicht gut abbilden; Anarchismus wird bei Heywood als Beispiel genannt. Zudem manifestieren sich Ideologien je nach geografischem Kontext unterschiedlich, und neue Ideologien lassen sich wegen ihres Kultur- und Identitätsfokus nicht immer einfach in den klassischen Links-Rechts-Konflikt einordnen.',s:'Heywood (2021), Kap. 1, S. 16–18'},
 {id:'i41',topic:'Ideologien',type:'Vergleich',q:'Was ergänzt ein zweidimensionales politisches Spektrum gegenüber dem linearen Modell?',a:'Es behält die horizontale Links-Rechts-Achse bei und ergänzt eine vertikale Achse von <b>Freiheit zu Autorität beziehungsweise Herrschaft</b>. Damit soll sichtbar werden, dass wirtschafts- oder gleichheitspolitische Positionen allein nicht alle relevanten Unterschiede politischer Ideologien erfassen.',s:'Heywood (2021), Kap. 1, S. 17'},
 {id:'i42',topic:'Ideologien',type:'Verständnis',q:'Was meint die These vom „Ende der Ideologie“ bei Daniel Bell – und wie wird sie im Text eingeordnet?',a:'Bell beobachtete nach dem Zweiten Weltkrieg im Westen einen breiten Konsens der großen Parteien und eine Verlagerung auf technische Fragen des Wohlstands. Heywood ordnet dies nicht als echtes Ende der Ideologie ein, sondern als zeitweilige Dominanz eines selbst ideologischen Konsenses um gelenkten Kapitalismus beziehungsweise Wohlfahrtskapitalismus.',s:'Heywood (2021), Kap. 1, S. 18–19'}
];

